/* Kavico v353 — FAQ accordion/search with category-group visibility. */
(function(){'use strict';function init(){var items=Array.from(document.querySelectorAll('.faq-item'));if(!items.length)return;items.forEach(function(item){var q=item.querySelector('.faq-q');if(!q)return;q.setAttribute('aria-expanded',item.classList.contains('open')?'true':'false');q.addEventListener('click',function(){var will=!item.classList.contains('open');items.forEach(function(i){i.classList.remove('open');var b=i.querySelector('.faq-q');if(b)b.setAttribute('aria-expanded','false');});if(will){item.classList.add('open');q.setAttribute('aria-expanded','true');}});});var toolbar=document.querySelector('[data-faq-toolbar]'),list=document.querySelector('[data-faq-list]');if(!toolbar||!list)return;var input=document.getElementById('faqSearch'),chips=Array.from(toolbar.querySelectorAll('[data-fcat]')),groups=Array.from(list.querySelectorAll('[data-faq-group]')),empty=document.getElementById('faqNoResults');function filter(){var active=chips.find(function(b){return b.classList.contains('is-active');}),cat=active?(active.dataset.fcat||'all'):'all',query=(input&&input.value||'').trim().toLowerCase(),visible=0;items.forEach(function(item){var text=(item.innerText||item.textContent||'').toLowerCase(),c=item.dataset.cat||'all',show=(!query||text.indexOf(query)!==-1)&&(cat==='all'||c===cat);item.hidden=!show;if(show)visible++;});groups.forEach(function(g){g.hidden=!Array.from(g.querySelectorAll('.faq-item')).some(function(i){return !i.hidden;});});if(empty)empty.hidden=visible!==0;}chips.forEach(function(btn){btn.setAttribute('aria-pressed',btn.classList.contains('is-active')?'true':'false');btn.addEventListener('click',function(){chips.forEach(function(b){b.classList.remove('is-active');b.setAttribute('aria-pressed','false');});btn.classList.add('is-active');btn.setAttribute('aria-pressed','true');filter();});});if(input){input.addEventListener('input',filter);input.addEventListener('keydown',function(e){if(e.key==='Escape'){input.value='';filter();input.blur();}});}filter();}if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init,{once:true});else init();})();
